#ifndef __NINGPO_GAMETEXT_H__
#define __NINGPO_GAMETEXT_H__

// The few strings of Ning Po's exe that the player sees (the best times' default names) are read from the player's
// own Ningpo.exe at start-up, by address: by the user's decision (2026-10-19) no game text is in the repository.
//
// - GameTextTable.inc (generated by games/ningpo/tools/make_gametext.py from the GT() and GTA() of src/) lists each
//   string's address in the game image, its length and a hash: no text.
// - LoadGameTexts() reads Ningpo.exe from the game folder, takes each string at its address and checks length and
//   hash. A string that does not match (another version of the exe) stays empty and is logged.
// - Code names a string by its address in the original: GT(0x00467a24); a table of addresses marks each with
//   GTA(). Overrides: any string property named GT_<8 hex digits> replaces the string read from the exe.

#include <cstdint>

namespace ningpo
{

// Reads the strings from the game folder's executable and applies the string-property overrides. Returns false
// when the executable is missing or no string matched.
bool LoadGameTexts();
// The string the original keeps at theVA; "" for an address that is not in the table
const char* GameText(uint32_t theVA);

} // namespace ningpo

#define GT(theVA) (::ningpo::GameText(theVA))
#define GTA(theVA) (theVA)

#endif
